INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
  ('b0000000-0000-0000-0007-000000000000', 'TypeScript란 무엇이며, JavaScript에 어떤 이점을 제공하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000001', 'TypeScript의 기본 타입에는 어떤 것들이 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000002', '인터페이스(interface)와 타입 별칭(type alias)의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000003', 'Generics(제네릭)란 무엇이며 어떻게 활용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000004', 'TypeScript에서 any 타입은 언제 사용하는 것이 적절한가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000005', 'null과 undefined는 TypeScript에서 어떻게 처리되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000006', 'TypeScript의 tsc 컴파일러가 하는 일은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000007', 'TypeScript에서 declare 키워드는 언제 사용하나요?', 'HARD', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000008', 'TypeScript에서 타입 단언(Type Assertion)이란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-000000000009', 'TypeScript에서 유니온 타입(Union Types)과 교차 타입(Intersection Types)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000a', 'TypeScript 프로젝트에서 tsconfig.json 파일의 역할은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000b', '타입 가드(Type Guards)란 무엇이며, 어떤 경우에 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000c', 'TypeScript에서 인터페이스의 확장(extension)은 어떻게 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000d', '함수 오버로드(Function Overload)는 TypeScript에서 어떻게 구현되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000e', 'TypeScript에서 제네릭(Generic)을 사용하여 함수나 클래스를 정의하는 방법은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000007'),
  ('b0000000-0000-0000-0007-00000000000f', 'TypeScript와 Babel을 함께 사용할 때의 장점은 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000007');
